#!/usr/bin/env python3
"""Scripts grounded in observed configuration and saved training-app behavior."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parent
course=json.loads((ROOT/'course.json').read_text())
rows={l['id']:l for l in course['lessons']}
def scene(title,captures,narration):return {'title':title,'captures':captures,'narration':narration}
lessons=[
{'id':'02-department-settings','scenes':[
scene('Choose department behavior deliberately',['30-department-settings-start.jpg'],
"Department settings change how a whole department sees and handles its work. They deserve the same review as a dispatch procedure. Open the department menu, then Department Settings. We are using the fictional Firehouse fifty-one department, but these controls are equally relevant to a mobile crisis service, a search team, a patrol company, a wildland contractor, or a plant response team. Begin by identifying the problem you want to solve. Is the roster showing stale availability? Are off-duty members receiving unwanted alerts? Is a module confusing members who do not use it? Make one deliberate change, save it, and check its effect before changing several related controls."),
scene('Time, ownership and automatic availability',['30-department-settings-start.jpg'],
"The department name identifies this workspace. The time zone affects local time displays and scheduled work; our training department uses Central Time. Use twenty-four-hour time changes how supported screens display the clock. It does not create twenty-four-hour staffing coverage. Account Owner identifies the managing account; review ownership and administrative access in the personnel and security workflows. Disable Auto-Available controls the automatic behavior described on this screen: setting personnel status to Available after an hour. In this lesson we turn that automatic behavior off. This avoids treating the passage of time as evidence that a person has finished a long assignment. It also makes deliberate member updates and supervisor follow-up more important. Saving the setting is separate from proving the worker’s behavior over time; this recording verifies the saved configuration, not a one-hour background-worker test."),
scene('Review communications and recovery settings',['30-department-settings-start.jpg'],
"Modern notifications selects supported modern notification behavior, including modern push sounds. It does not establish a valid device registration or prove delivery. Review every channel and consumer your department uses. Require password resets by email directs administrator-initiated member resets through single-use recovery links instead of an administrator selecting a member’s password. Require Security PIN governs sensitive supported assistant and text actions. These are security decisions, and the owning administrator needs to review recovery arrangements and member enrollment. We leave their existing values visible and discuss their impact without changing credentials. T T S Language selects the application’s voice-prompt language. That setting is separate from the Warm Lulu narration used in this training video."),
scene('Set a usable roster order and map starting point',['31-address-map-center.jpg'],
"Under Sorting, we choose LastName for personnel. Units and calls have their own order settings. This is useful when a dispatcher knows the member’s surname and needs a predictable roster. The Address section describes the department base or office. Our address is fictional. Default Map Center accepts decimal latitude and longitude. Explicit coordinates pin the starting point; leaving both blank lets the system work out a center from the saved address. A department center is a map starting point, not a live unit location, a patrol boundary, or proof that a resource is present. A search team can use its base, a security company its operational office, and an industrial team its facility access point. For a contractor deployment, review whether the department center or an incident-specific view is appropriate."),
scene('Separate staffing reset from status reset',['32-staffing-status-reset-controls.jpg','33-staffing-reset-configured.jpg'],
"Personnel Staffing Reset and Personnel Status Reset are different controls. Staffing describes availability; status describes current activity. Our example enables the daily staffing reset at eight a m and selects Unavailable as its target. Members then need to declare their availability after the reset. This can help a volunteer search department avoid relying on yesterday’s availability, or a wildland contractor require a fresh crew check. It can also disrupt a team working overnight if the time and target do not fit its procedures. The daily status reset remains off in this example. Consider extended searches, patrol assignments, mental health responses and plant incidents before automatically replacing a current activity status. When you create custom personnel staffing or status sets, revisit these target selections; the intended label must resolve to the current option."),
scene('Understand suppression before enabling it',['34-staffing-suppression-configured.jpg'],
"The staffing suppression section lets the department select staffing levels that should be muted by supported notification paths. We enable suppression and select Unavailable. Review the interaction carefully: at the daily reset, members are marked Unavailable, and supported notifications can suppress them until their staffing is updated. This reduces off-duty noise, but a stale staffing declaration can exclude the person you intended to reach. For security, the procedure might distinguish on-duty patrol from off-duty staff. A mobile response service might distinguish the scheduled response team from the broader roster. An industrial team might distinguish the current plant E R T from other employees. Verify the intended recipients and fallback procedures. This isolated training stack does not send real alerts, so this lesson does not claim an external delivery test."),
scene('Save, reopen and verify the values',['35-department-settings-persisted.jpg'],
"Click Save, then reopen the settings. In this build the department form does not show a useful success banner, so reopening is an important persistence check. Our saved values show Disable Auto-Available checked, LastName sorting, daily staffing reset enabled at eight a m to Unavailable, daily status reset off, and suppression enabled for Unavailable. These are the values actually retained by the application. Force Department Update requests a department cache refresh if clients retain stale department information. Read its timing notice and allow clients to refresh or sign in again where appropriate. A cache refresh is not a substitute for saving a form or testing a notification channel. Investigate the owning screen and saved value first."),
scene('Demonstrate a module switch and retained data',['36-module-settings.jpg','37-calendar-module-disabled.jpg','38-calendar-module-restored.jpg'],
"Open Department Modules. These switches control supported module availability and navigation. Turning a module on does not purchase its add-on, grant missing permissions, or configure an external provider. We turn Calendar off and save. The page confirms the module settings were saved, and Calendar disappears from the side menu. We then turn Calendar back on, save, and reopen it. The three original training events are still present. Disabling the module did not delete those records. The screen also warns that propagation can differ across features, so review the screens and apps your department actually uses. For your practice exercise, select one behavior, explain who it affects, save it in a training department, reopen it and inspect the result. Document the responsible reviewer and an operational test for any effect this configuration check cannot prove.")],
'observed_results':['Disable Auto-Available retained after reload','Personnel sorting LastName retained','Daily staffing reset 08:00 to Unavailable retained','Unavailable suppression retained','Calendar disabled and restored; three original events remained'],
'limitations':['Synthetic isolated department','No external notification delivery','No elapsed one-hour or scheduled reset worker test','No credential or account-owner change']},
{'id':'03-custom-statuses','scenes':[
scene('Choose the right status family',['17-custom-statuses-start.jpg'],
"Useful statuses let the department tell the difference between a resource that can accept work and a resource that is already doing something. Open the department menu and Custom Statuses. The page separates unit status sets, personnel actions, and personnel staffing levels. Unit status sets describe vehicles, apparatus or field resources. Personnel actions describe what a person is doing. Staffing describes whether that person is available. A security patrol can be available while On Patrol; a search volunteer can be unavailable for deployment even if the last activity says Standing By. Avoid trying to answer all those questions with one label. The Chicago Fire names are simply our synthetic demo roster. These status concepts also serve mobile response, search and rescue, security, wildland and industrial teams."),
scene('Start with a relevant template',['18-status-templates-sectors.jpg','19-status-template-customized.jpg','20-custom-statuses-saved.jpg'],
"Choose Add Unit Statuses. Resgrid offers starting templates for ambulance, fire, law enforcement, search and rescue, general response, disaster response, security, industrial fleets and logistics. Pick the one that fits the resource’s actual lifecycle. We choose Search and Rescue, name the set Training, S A R Field Team, and rename Searching to Searching assigned area. Templates prefill options; they do not save the set. You can review labels, colors and ordering before clicking Add. The saved set contains eight options. A security company can start from Security and use On Patrol and Investigating. An industrial team can use fleet and equipment states such as Maintenance. A mobile response team can use a reviewed response lifecycle. A wildland contractor can use staging and response states appropriate to its crews and apparatus."),
scene('A label and its system meaning are separate',['24-option-edit-not-persisted.jpg'],
"Inspect an option’s Base Type. Searching has the meaning of actively searching an assigned area, sector or grid. A clearer button label can preserve that meaning. Choosing None creates an informational state without that system meaning. A label that says Ready should not be assigned an Unavailable meaning, and an attractive green button is not evidence of readiness. Review color contrast and use meaningful text so members do not have to rely on color alone. This build exposed an option-edit issue: changing the note and destination requirements and clicking Update returned to the list, but reopening the option showed the old values. We recorded that limitation and do not call the edit successful. The next part demonstrates recording the requirements during creation, then checking the saved result."),
scene('Build an option with meaning and requirements',['25-blank-status-option.jpg','26-create-searching-requirements.jpg'],
"Use Start from Blank to build the Training, Field Response set. Add Option opens the option dialog. Our first option is Ready for assignment with the Available base meaning, a dark green background, white text and an optional note. Our second is Searching assigned area with Searching meaning. We choose Calls as its detail type, Required for its note type, and Require G P S. These controls express different requirements: the detail supplies a destination such as an incident; the note supplies context; the location requirement supplies a position where supported by the client. A search team might record the assigned area and team accountability. A security patrol might record the site or investigation reference. Keep mobile response notes within approved operational-record procedures; a required note is not an invitation to place sensitive clinical detail in every status update."),
scene('Order and save the whole set',['27-field-status-set-ready.jpg'],
"Our third option is Unavailable, maintenance, with the Unavailable meaning and a required note. This makes an equipment defect visible without suggesting that the resource remains ready for dispatch. Set the order to zero, one and two so Ready, Searching and Unavailable appear predictably. Adding an option to the dialog’s table is still an unsaved change. Click Add on the main form to save the entire set. The application returns to Custom Statuses and shows the three-option Field Response set. Review that result before assigning it. For an industrial response team, this pattern can keep defective equipment out of normal readiness assumptions. For wildland or search teams, it can distinguish staging and active work from unavailable equipment. More options are useful only if members can select them consistently."),
scene('Assign unit statuses through the unit type',['22-unit-type-status-assignment.jpg','23-custom-unit-picker.jpg'],
"A new unit status set needs to be assigned before a unit can use it. Open Types, find the Rescue unit type, and choose Field Response under Actions, Custom Unit Statuses. Save the assignment. This changes the status choices for every unit that uses the Rescue type in this department. Squad Three is our example rescue unit. Reopen its status picker and check that Ready for assignment, Searching assigned area, and Unavailable maintenance are present. For a security department, you might assign a patrol status set to its patrol vehicle type. For an industrial team, separate equipment types can use different operational choices. A type assignment changes the available choices for all units of that type. Changing one unit's current status affects that unit."),
scene('Record and verify a real status update',['28-search-status-call-note.jpg','29-search-status-saved.jpg'],
"Select Searching assigned area. The destination picker now includes the active training calls because Calls was recorded at creation. We choose the vehicle rescue exercise and enter an accountability note for assigned area Alpha. Click Save. The unit list now displays Searching assigned area with a new timestamp for Squad Three. That is the observed saved result. The web path shown here does not demonstrate a device G P S capture or all mobile-client enforcement, so we do not claim that it proves the location requirement. Test the member and unit apps your department uses, including missing notes, unavailable location permission and offline conditions. A saved status is a declaration of activity; it does not prove the team completed a search, reached a subject, or has an independently verified position."),
scene('Adapt and practice the workflow',['17-custom-statuses-start.jpg','29-search-status-saved.jpg'],
"Personnel actions and staffing have separate template entry points on the original page. Before replacing either department-wide set, review existing reset targets, suppression selections, dispatch transitions and member training. For community paramedicine or mental health response, use approved operational states such as En route to visit or Contact made, with meanings appropriate to the work. For search and rescue, use Searching and Subject Contact. For security, use On Patrol and Investigating. For wildland contractors, use Staging, Responding and Returning. For industrial teams, distinguish response activity from equipment Maintenance and Unavailable. Your practice exercise is to create a small set in a training department, explain each option’s meaning, assign it to the intended unit type, save a real update and verify its display. Record any client behavior that still needs an operational test and assign the next review to the responsible person.")],
'observed_results':['SAR template saved with eight options','Three-option Field Response set created with explicit meanings, note and destination settings','Rescue type assigned to Field Response','Squad 3 saved Searching assigned area with call 51003 and accountability note'],
'limitations':['Fresh training sequences required reservation of built-in IDs <=25; existing rows preserved','Option-edit requirements did not persist in this build; creation path used and verified','Web save did not prove GPS or mobile-client note enforcement','Personnel and staffing template entry points reviewed; replacements not applied in this lesson']}
]
for lesson in lessons:
    ident=lesson['id'];l=rows[ident];lesson.update(title=l['title'],scope=l['topics'],voice='Warm Lulu',source_type='Actual application captures; guided cuts; synthetic training data',cross_sector_examples=l['sector_examples'])
    (ROOT/'lessons'/f'{ident}.json').write_text(json.dumps(lesson,ensure_ascii=False,indent=2)+'\n')
    l['status']='captured-scripted';l['script_words']=sum(len(s['narration'].split()) for s in lesson['scenes'])
(ROOT/'course.json').write_text(json.dumps(course,ensure_ascii=False,indent=2)+'\n')
print(json.dumps([{k:l[k] for k in ['id','script_words','status']} for l in course['lessons'] if l['id'] in {x['id'] for x in lessons}]))
